import{_ as s,o as t,c as o,a0 as n}from"./chunks/framework.ChlVJx0I.js";const l=JSON.parse('{"title":"Drop the pruning, compress, and quota extensions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0046-drop-pruning-compress-and-quota.md","filePath":"adr/0046-drop-pruning-compress-and-quota.md","lastUpdated":1792406981000}'),r={name:"adr/0046-drop-pruning-compress-and-quota.md"};function a(i,e,d,h,c,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="drop-the-pruning-compress-and-quota-extensions" tabindex="-1">Drop the pruning, compress, and quota extensions <a class="header-anchor" href="#drop-the-pruning-compress-and-quota-extensions" aria-label="Permalink to &quot;Drop the pruning, compress, and quota extensions&quot;">​</a></h1><p>The package no longer ships the Pruning, Compress, and Quota extensions. Twelve weeks of session evidence (2,842 sessions, 252k tool results) showed none of the three in use: Pruning was disabled in the user&#39;s settings with zero activity across the whole corpus; Compress was used in one two-day burst (10 compression spans, Sep 18-19) and then disabled; Quota was disabled in both the package filter and the global extension list, with zero <code>/quota</code> invocations, and it monitors only the OpenAI ChatGPT plan while the user&#39;s OpenAI traffic is Codex, which the Quota source does not read. The user maintained, type-checked, and installed roughly 3,300 lines of extensions, tests, docs pages, ADRs, and glossary terms in every session on every machine for tools that do not run.</p><p>The three extension directories, their docs pages and screenshots, their capture pipeline entries, and their test directories are deleted, and the <code>e2e:quota</code> (and, with the pruning probe, the <code>e2e:pruning</code>) manifest scripts are removed. The Quota source module - the ChatGPT plan token refresh, the usage read, the Quota window and usage snapshot types, the read contract, and the provider-id and endpoint constants - moves into the model-router extension as <code>extensions/model-router/source.ts</code>. The router&#39;s wait strategy and switch-back read the plan&#39;s quota windows through it, and the extension entry point builds it; both now import from the router&#39;s own directory. The module&#39;s contract is unchanged: one read of the plan&#39;s quota windows, never throws, and the token refresh stays one owned module with its documented behavior (refresh on expiry or 401, read-modify-write on pi&#39;s auth store, one retry after a re-read before declaring the login dead).</p><p>This ADR supersedes ADR 0005 (the Quota extension refreshes the ChatGPT token itself; model-router now owns the refresh), ADR 0011 (pruning as a request-level projection), ADR 0015 (compression as a request-time view), and ADR 0018 (sticky pruning engagement). The superseded files stay in the index, marked superseded, as the record of why those designs were made and what they guaranteed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>No surviving extension changes behavior: outside model-router the diff is imports, test fixtures, docs, and deletions. The usage scan still counts <code>compress-span</code> entries that old sessions recorded, and the model-router&#39;s wait strategy reads the plan&#39;s windows exactly as before, now from its own module.</li><li>The glossary&#39;s Pruning and Compression sections are deleted; the Quota terms (Quota window, Usage snapshot, Quota source, and the model-router&#39;s Quota halt vocabulary) live under the Model router section.</li><li>The docs site, README, and screenshot pipeline describe only the shipped set, so the <code>npm run docs:screenshots</code> and VitePress build gates pass with the dropped views gone.</li><li>The user&#39;s own settings carry stale lines the repo cannot delete: three package-filter entries (<code>extensions/pruning|compress|quota/index.ts</code> disable lines), an orphaned global disable of the quota extension, and the <code>compress</code> and <code>pruning</code> config blocks. They are deleted by hand after the merge; the drift check&#39;s stale-entry class surfaces any that remain.</li></ul>',6)])])}const m=s(r,[["render",a]]);export{l as __pageData,m as default};
